import{f as t,o as i,c as d,a6 as o}from"./chunks/framework.DuKjrNUc.js";const u=JSON.parse('{"title":"noorm pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"cli/pipeline.md","filePath":"cli/pipeline.md"}'),n={name:"cli/pipeline.md"};function a(s,e,r,c,l,p){return i(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="noorm-pipeline" tabindex="-1"><code>noorm pipeline</code> <a class="header-anchor" href="#noorm-pipeline" aria-label="Permalink to “noorm pipeline”">​</a></h1><p>Run a named SQL workflow and inspect its config-scoped history. Define the workflow first as described in <a href="/guide/sql-pipelines.html">SQL pipelines</a>.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipeline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> close-period</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;period&quot;:&quot;2026-10&quot;,&quot;batchSize&quot;:5}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-accounting=false</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipeline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> history</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> close-period</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipeline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><p>Place the global <code>--cwd</code> before <code>pipeline</code>. Put operation flags after the slug or subcommand. In this example <code>--batch-size 0</code> overrides the JSON value, and <code>false</code> and <code>0</code> remain typed values.</p><p>For native review, typed input forms, confirmation, and history lookup, see <a href="/guide/pipeline-terminal.html">Pipelines in the terminal</a>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to “Run”">​</a></h2><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>noorm pipeline run &lt;slug&gt; [--input &lt;json&gt;] [generated input flags] [--dry-run] [--config &lt;name&gt;] [--yes] [--json]</span></span></code></pre></div><p><code>run</code> requires one slug. The explicit command keeps workflow names independent of CLI commands: <code>noorm pipeline run history</code> executes the workflow named <code>history</code>. Bare-slug execution is not supported.</p><p>Use <code>noorm pipeline --help</code> to list the static <code>run</code>, <code>history</code>, and <code>show</code> commands, or <code>noorm pipeline run --help</code> to see the required slug positional. Neither loads a manifest, settings, secrets, or a database connection.</p><p><code>--input</code> must be a JSON object. Each declared lowerCamelCase input produces a kebab-case flag. Explicit flags override JSON properties, then defaults fill absent values. Boolean flags accept <code>--flag=true</code> and <code>--flag=false</code>; object and array flags take JSON. Use <code>noorm pipeline run &lt;slug&gt; --help</code> to see that definition&#39;s descriptions, types, required fields, defaults, and choices. Definition-specific help reads the selected manifest offline without loading secrets, rendering SQL, or connecting.</p><p>Missing required values prompt only when stdin and stdout are terminals and the invocation is not CI, JSON, <code>--yes</code>, <code>NOORM_YES</code>, or the agent channel. Otherwise supply every required value. Invalid explicit values and cancelled prompts stop before admission. Input flag names cannot collide with built-in flags.</p><p><code>--dry-run</code> validates and renders all declarations without creating history, claiming a guard, or executing workflow SQL. Trusted template helpers can still have side effects. Both normal and dry runs enforce <code>pipeline:run</code> access policy. <code>pipeline history</code> and <code>pipeline show &lt;run-id&gt;</code> read through <code>explore</code>, which gates the agent channel only.</p><h2 id="history-and-show" tabindex="-1">History and show <a class="header-anchor" href="#history-and-show" aria-label="Permalink to “History and show”">​</a></h2><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>noorm pipeline history &lt;slug&gt; [--limit &lt;number&gt;] [--config &lt;name&gt;] [--json]</span></span>
<span class="line"><span>noorm pipeline show &lt;run-id&gt; [--config &lt;name&gt;] [--json]</span></span></code></pre></div><p>History defaults to 20 runs and accepts an integer from 1 through 100. It lists newest run IDs first. Show requires a positive safe integer and returns the run with declaration-ordered steps. Both commands use the selected config; a run in another config is not found.</p><p>Input values and rendered SQL are not included in ordinary output or stored in pipeline history. History may lag execution while workflow activity settles. A protected run can retain its guard when activity is uncertain; use <a href="/guide/pipeline-recovery.html">pipeline recovery</a>, not an automatic retry or force unlock.</p><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to “Exit codes”">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>Success, dry run, or help.</td></tr><tr><td><code>1</code></td><td>Failure, busy, blocked by policy, a run ID that does not exist, or unknown outcome without confirmed partial committed work.</td></tr><tr><td><code>2</code></td><td>Invalid definition, input, or invocation, including an unknown pipeline.</td></tr><tr><td><code>3</code></td><td>Confirmed partial committed work. Inspect history before deciding what to do next.</td></tr><tr><td><code>130</code></td><td>A second Ctrl+C. The process exits without waiting for the run to settle.</td></tr></tbody></table><p>The first Ctrl+C aborts the run and the command waits for it to settle. The second exits <code>130</code> at once. Running SQL may continue on the server, and history may not have settled, so check <a href="/guide/pipeline-recovery.html">pipeline recovery</a> before retrying.</p><h2 id="error-messages" tabindex="-1">Error messages <a class="header-anchor" href="#error-messages" aria-label="Permalink to “Error messages”">​</a></h2><p>The messages in this table can name inputs, never their values, and never include rendered SQL, paths, or database error text.</p><table tabindex="0"><thead><tr><th>Message</th><th>Exit</th><th>Cause</th></tr></thead><tbody><tr><td><code>Pipeline not found</code></td><td><code>2</code></td><td>The slug names no pipeline folder under <code>paths.pipelines</code>.</td></tr><tr><td><code>Invalid pipeline definition (&lt;rule&gt;)</code></td><td><code>2</code></td><td>The manifest or a step failed the named rule.</td></tr><tr><td><code>Invalid pipeline definition or invocation</code></td><td><code>2</code></td><td>A command that loads a definition failed for a reason that is not a named rule or an unknown slug.</td></tr><tr><td><code>Invalid or cancelled pipeline input or invocation</code></td><td><code>2</code></td><td><code>run</code> rejected an argument or the interactive input prompt was cancelled.</td></tr><tr><td><code>Missing required pipeline inputs: &lt;names&gt;</code></td><td><code>2</code></td><td>A non-interactive <code>run</code> lacks required inputs. The message lists their names.</td></tr><tr><td><code>Invalid pipeline input</code></td><td><code>2</code></td><td>The SDK rejected input the CLI accepted.</td></tr><tr><td><code>Invalid pipeline run ID or invocation</code></td><td><code>2</code></td><td><code>show</code> got a bad run ID or argument.</td></tr><tr><td><code>Invalid pipeline history invocation</code></td><td><code>2</code></td><td><code>history</code> got a bad limit or argument.</td></tr><tr><td><code>Unable to read pipeline history</code></td><td><code>1</code></td><td><code>history</code> could not read the run table.</td></tr><tr><td><code>Pipeline execution failed</code></td><td><code>1</code></td><td>Any other failure during a run.</td></tr><tr><td><code>Pipeline run not found</code></td><td><code>1</code></td><td><code>show</code> found no such run ID in the selected config.</td></tr><tr><td><code>Pipeline execution is blocked by the config policy or requires confirmation; pass --yes</code></td><td><code>1</code></td><td>A protected config blocks the run, or it needs confirmation.</td></tr><tr><td><code>Pipeline execution is blocked by the config policy</code></td><td><code>1</code></td><td>The same, when <code>--yes</code> was already passed. Confirmation cannot lift it.</td></tr><tr><td><code>Pipeline execution was not admitted</code></td><td><code>1</code></td><td>A <code>singleRun</code> pipeline already has an active run.</td></tr></tbody></table><p>Some failures exit <code>1</code> with the driver&#39;s message, which may not be safe to publish: <code>Failed to create context: …</code>, <code>Failed to connect: …</code> and <code>Failed to initialize database schema: …</code> for connection, context and schema-version failures, and any database error thrown while <code>show</code> or <code>history</code> reads the run tables.</p><p><code>&lt;rule&gt;</code> is one of:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Failed check</th></tr></thead><tbody><tr><td><code>slug</code>, <code>pipelines-path</code></td><td>The slug or the configured <code>paths.pipelines</code> is not a safe relative name.</td></tr><tr><td><code>missing-directory</code>, <code>missing-file</code></td><td><code>missing-directory</code>: the configured <code>paths.pipelines</code> root does not exist. <code>missing-file</code>: the manifest or a step SQL file does not exist.</td></tr><tr><td><code>unreadable-path</code>, <code>path-kind</code>, <code>path-escape</code></td><td>A path cannot be read, is the wrong kind, or resolves outside its directory.</td></tr><tr><td><code>yaml</code>, <code>manifest-schema</code></td><td>The manifest is not valid YAML, or does not match the manifest schema.</td></tr><tr><td><code>input-name</code>, <code>input-default</code>, <code>input-choices</code>, <code>input-default-choice</code></td><td>An input name, default, or choice list is invalid.</td></tr><tr><td><code>mixed-dependencies</code>, <code>duplicate-step</code>, <code>step-dependency</code>, <code>dependency-cycle</code></td><td>Steps mix linear and graph styles, repeat an ID, name a bad dependency, or form a cycle.</td></tr><tr><td><code>step-sql-path</code></td><td>A step SQL path is unsafe or not a <code>.sql</code> or <code>.sql.tmpl</code> file.</td></tr><tr><td><code>step-prepare</code></td><td>A step failed to render.</td></tr><tr><td><code>escape-unavailable</code></td><td>A step template called <code>$.escape</code>, which pipelines do not support. Use <code>$.quote</code>.</td></tr><tr><td><code>transaction-control</code></td><td>A step contains transaction control or an implicit commit under managed transactions. A PostgreSQL <code>BEGIN ATOMIC ... END</code> body is rejected too, because its <code>END</code> cannot be told from a transaction end.</td></tr></tbody></table>`,25)])])}const g=t(n,[["render",a]]);export{u as __pageData,g as default};
